const items = $input.all();

function decodeBase64(data) {
  if (!data) return '';

  const normalized = data
    .replace(/-/g, '+')
    .replace(/_/g, '/');

  return Buffer.from(normalized, 'base64').toString('utf8');
}

function findTextPart(payload) {
  if (!payload) return '';

  if (payload.body?.data) {
    return decodeBase64(payload.body.data);
  }

  if (Array.isArray(payload.parts)) {
    // Prefer plain text
    for (const part of payload.parts) {
      if (part.mimeType === 'text/plain' && part.body?.data) {
        return decodeBase64(part.body.data);
      }
    }

    // Otherwise search recursively
    for (const part of payload.parts) {
      const result = findTextPart(part);
      if (result) return result;
    }
  }

  return '';
}

function getHeader(headers, name) {
  if (!Array.isArray(headers)) return '';

  const header = headers.find(
    h => h.name && h.name.toLowerCase() === name.toLowerCase()
  );

  return header?.value || '';
}

return items.map(item => {
  const data = item.json;

  const headers = data.payload?.headers || [];

  const content = findTextPart(data.payload);

  return {
    json: {
      id: data.id || '',
      threadId: data.threadId || '',

      sender: getHeader(headers, 'From'),
      recipient: getHeader(headers, 'To'),
      subject: getHeader(headers, 'Subject'),
      date: getHeader(headers, 'Date'),

      content: content
    }
  };
});

return items.map(item => {
  const data = item.json;

  return {
    json: {
      newsletter_id: data.id || '',
      sender: data.sender || '',
      recipient: data.recipient || '',
      subject: data.subject || '',
      date: data.date || '',
      content: data.content || ''
    }
  };
});

function collectParts(part, result = []) {
  if (!part) return result;

  if (part.mimeType) {
    result.push(part);
  }

  if (Array.isArray(part.parts)) {
    for (const child of part.parts) {
      collectParts(child, result);
    }
  }

  return result;
}

function extractImageUrls(html) {
  if (!html) return [];

  const urls = [];

  const regex = /<img[^>]+src=["']([^"']+)["']/gi;
  let match;

  while ((match = regex.exec(html)) !== null) {
    urls.push(match[1]);
  }

  return [...new Set(urls)];
}

return $input.all().map(item => {
  const data = item.json;
  const payload = data.payload || {};

  const parts = collectParts(payload);

  // Find image MIME parts
  const imageParts = parts
    .filter(part => part.mimeType && part.mimeType.startsWith('image/'))
    .map(part => ({
      mimeType: part.mimeType,
      filename: part.filename || '',
      attachmentId: part.body?.attachmentId || '',
      size: part.body?.size || 0,
      contentId: part.headers?.find(
        h => h.name?.toLowerCase() === 'content-id'
      )?.value || ''
    }));

  // Find HTML parts
  const htmlParts = parts.filter(
    part => part.mimeType === 'text/html'
  );

  const imageUrls = [];

  for (const part of htmlParts) {
    // Gmail API body.data may contain base64url encoded HTML
    if (part.body?.data) {
      try {
        const html = Buffer.from(
          part.body.data
            .replace(/-/g, '+')
            .replace(/_/g, '/'),
          'base64'
        ).toString('utf8');

        imageUrls.push(...extractImageUrls(html));
      } catch (error) {
        // Ignore malformed HTML encoding
      }
    }
  }

  return {
    json: {
      id: data.id || '',
      threadId: data.threadId || '',
      sender: data.sender || '',
      recipient: data.recipient || '',
      subject: data.subject || '',
      date: data.date || '',

      imageParts,

      imageUrls: [...new Set(imageUrls)],

      imageCount:
        imageParts.length +
        [...new Set(imageUrls)].length
    }
  };
});

const output = [];

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const data = item.json;
  const imageUrls = data.imageUrls || [];

  for (let j = 0; j < imageUrls.length; j++) {
    const imageUrl = imageUrls[j];

    output.push({
      json: {
        emailId: data.id,
        image_id: `${data.id}_image_${j + 1}`,
        image_number: j + 1,
        sender: data.sender,
        subject: data.subject,
        date: data.date,
        imageUrl: imageUrl
      },

      pairedItem: {
        item: i
      }
    });
  }
}

return output;

const items = $input.all();

return items.filter(item => {
  const binary = item.binary?.data;

  if (!binary) {
    return false;
  }

  const mimeType = binary.mimeType || '';
  const fileSize = binary.fileSize || '';

  // Only keep actual image formats
  const validImage = [
    'image/jpeg',
    'image/png',
    'image/webp',
    'image/gif'
  ].includes(mimeType.toLowerCase());

  // Convert n8n file size to bytes
  const match = fileSize.match(/^([\d.]+)\s*(B|KB|MB|GB)$/i);

  if (!match) {
    return false;
  }

  const size = parseFloat(match[1]);
  const unit = match[2].toUpperCase();

  const multipliers = {
    B: 1,
    KB: 1024,
    MB: 1024 * 1024,
    GB: 1024 * 1024 * 1024
  };

  const sizeInBytes = size * multipliers[unit];

  // Remove tiny tracking pixels and technical images
  return validImage && sizeInBytes > 5000;
});

const items = $input.all();

// Hent alle items fra Filter Images
const filterItems = $('Filter Images').all();

const imageAnalyses = [];

for (let i = 0; i < items.length; i++) {

  const item = items[i];

  // Find det tilsvarende billede i Filter Images
  const filterItem = filterItems[i];

  // Newsletter ID kommer fra det oprindelige emailId
  const newsletterId = filterItem?.json?.emailId || '';

  // Analyze image kan returnere outputtet direkte
  // eller som et array.
  let data = item.json;

  if (Array.isArray(data)) {
    data = data[0] || {};
  }

  // Hent selve teksten fra OpenAI-outputtet
  const text =
    data?.content?.[0]?.text ||
    data?.output?.[0]?.content?.[0]?.text ||
    '';

  let analysis;

  try {

    const cleaned = text
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    analysis = JSON.parse(cleaned);

  } catch (error) {

    analysis = {
      raw_text: text,
      parse_error: true
    };

  }

  imageAnalyses.push({
    image_number: i + 1,
    newsletter_id: newsletterId,
    analysis: analysis
  });
}


// Brug newsletter ID fra det første billede
const newsletterId =
  imageAnalyses[0]?.newsletter_id || '';


return [
  {
    json: {
      newsletter_id: newsletterId,
      image_analyses: imageAnalyses
    }
  }
];

const items = $input.all();

return items.map(item => {
  const text = item.json.output?.[0]?.content?.[0]?.text || '';

  const cleaned = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  const data = JSON.parse(cleaned);

  return {
    json: data
  };
});

const gmailItems = $('Get many messages').all();
const sheetItems = $('Get row(s) in sheet').all();

// Alle newsletter IDs, der allerede findes i Google Sheets
const existingIds = new Set(
  sheetItems
    .map(item => String(item.json.newsletter_id ?? '').trim())
    .filter(Boolean)
);

// Behold kun Gmail-mails, der IKKE allerede findes i Sheet
const newNewsletters = gmailItems.filter(item => {
  const gmailId = String(item.json.id ?? '').trim();

  return gmailId && !existingIds.has(gmailId);
});

return newNewsletters;
